export default function nextDocument({ events, previousState, updatedRows, updatedCells }) {
  if (!Array.isArray(events)) throw new Error("Expected the complete Drive event batch");
  let index = 0,
    completed = [];
  if (previousState != null) {
    if (
      !Number.isInteger(previousState.index) ||
      !Array.isArray(previousState.completed) ||
      previousState.index < 1 ||
      previousState.index > events.length ||
      previousState.completed.length !== previousState.index - 1
    )
      throw new Error("Invalid document batch state");
    if (updatedRows !== 1 || updatedCells !== 3)
      throw new Error("Sheet did not confirm one complete row; inspect it before replaying");
    index = previousState.index;
    completed = [...previousState.completed, events[index - 1].fileId];
  }
  const event = events[index];
  if (event == null)
    return {
      state: { index, completed },
      more: false,
      fileId: "none",
      name: "",
      email: "",
      count: completed.length,
    };
  if (
    event.eventType !== "file_created" ||
    event.itemType !== "file" ||
    typeof event.fileId !== "string" ||
    !event.fileId
  )
    throw new Error("Invalid new-file event");
  const user = event.lastModifyingUser ?? {};
  return {
    state: { index: index + 1, completed },
    more: true,
    fileId: event.fileId,
    name: typeof user.displayName === "string" ? user.displayName : "",
    email: typeof user.emailAddress === "string" ? user.emailAddress : "",
    count: completed.length,
  };
}

