export default function check({ fileId, documentId, text }) {
  if (
    typeof fileId !== "string" ||
    !fileId ||
    documentId !== fileId ||
    typeof text !== "string" ||
    !text.trim()
  )
    throw Error("Document ID or readable text is missing");
  return { text };
}

